const app=document.getElementById('app');
const state={row:3,side:'A',bay:5,level:2,view:location.hash==='#map'?'map':'entry',open:false,busy:false};
const rowNames={1:'برافو',2:'اللوجستي والادارة',3:'الاسبير',4:'المعسكر',5:'الفا'};
const pad=n=>String(n).padStart(2,'0');
const code=()=>`R${pad(state.row)}-${state.side}-S${pad(state.bay)}-L${pad(state.level)}`;
const sample=()=>state.row===3&&state.side==='A'&&state.bay===5&&state.level===2;

const bravoDistribution=[
[['SA-008','SA-010','SA010','SA-010','RB-004'],['RB-009','RB-007','SA-020'],['RB-006','RB-SA-013','SA-023','RB-005'],['SA-005','SA-006','SA-008','SA-009','RB-003'],['RB-002','RB-001'],[]],
[['SA-001','SA-002','SA-003','SA-004'],['SA-007','SA-011'],['RB-SA-014','SA-015'],['SA-019','SA-021'],['SA-018','SA-026'],['SA-025']]
];
const bravoBoxes=bravoDistribution.flatMap((bays,l)=>bays.flatMap((labels,b)=>labels.map((label,i)=>({id:`bravo-s${b+1}-l${l+1}-box${i+1}`,label,bay:b+1,level:l+1,position:i+1}))));
const locationBoxes=()=>window.warehouseAllBoxes?window.warehouseAllBoxes().filter(b=>b.row===state.row&&b.side===state.side&&b.bay===state.bay&&b.level===state.level):(state.row===1&&state.side==='A'?bravoBoxes.filter(b=>b.bay===state.bay&&b.level===state.level):[]);

const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const contentsFor=box=>window.warehouseContentsFor?window.warehouseContentsFor(box):bravoContents[box.label.replace(/^RB-SA-/,'SA-').replace(/^SA([0-9])/,'SA-$1')];
function renderContents(box){
 const content=contentsFor(box);
 if(!content)return '<div class="empty"><h2>المحتويات بانتظار المراجعة</h2><p>لم نجد الصندوق '+escapeHtml(box.label)+' في كشف المحتويات.</p></div>';
 const row=(item,child=false)=>`<li class="equipment-row ${child?'subitem':''}"><div><div class="equipment-name">${escapeHtml(item.name)}</div>${item.notes?`<p class="note">${escapeHtml(item.notes)}</p>`:''}</div><span class="quantity">${item.quantity==null?'الكمية غير مذكورة':'الكمية: '+escapeHtml(item.quantity)}</span></li>`;
 return `<div class="contents"><h2>محتويات الصندوق</h2><p class="note">الأسماء والكميات حسب الكشف المعتمد.</p><ul class="equipment-list">${content.items.map(item=>item.children.length?`<li class="equipment-group"><h3 class="equipment-name">${escapeHtml(item.name)}</h3>${item.notes?`<p class="note">${escapeHtml(item.notes)}</p>`:''}<p class="detail-label">الملحقات ومحتويات المجموعة</p><ul>${item.children.map(child=>row(child,true)).join('')}</ul></li>`:row(item)).join('')}</ul></div>`;
}

function renderBravo(){
const boxes=locationBoxes(),selected=boxes.find(b=>b.id===state.box);
if(selected){renderRb001(selected);return;}
app.innerHTML=`<div class="topline"><div><div class="breadcrumbs">${rowNames[state.row]} / الجهة ${state.side} / القسم ${pad(state.bay)} / لفل ${state.level}</div><h1>${selected?'الصندوق '+selected.label:'صناديق الموقع'}</h1></div><button data-action="${selected?'boxes':'back'}">${selected?'رجوع إلى الصناديق':'رجوع إلى الخريطة'} ←</button></div>
<section class="map-panel"><div class="map-head"><b dir="ltr">${code()}</b><span class="legend">${boxes.length} صناديق · مواقع الصناديق</span></div>
${selected?`<div class="empty"><h2 dir="ltr">${selected.label}</h2><p>الصندوق ${selected.position} في هذا الموقع</p></div>${renderContents(selected)}`:`<div class="box-grid">${boxes.map(b=>`<button class="box-card" data-box="${b.id}"><strong dir="ltr">${b.label}</strong><span>الصندوق ${b.position} في هذا الموقع</span><small>${contentsFor(b)?'عرض المحتويات ←':'المحتويات بانتظار المراجعة'}</small></button>`).join('')}</div><p class="note">كل صندوق مستقل، بما في ذلك الصناديق ذات الأرقام المتكررة.</p>`}
</section>`;
}

const toolsList=[['منشار يدوي',2,0,-230,-70,-110,-65],['شنطة أدوات',3,0,-120,-155,-62,-145],['مطرقة',0,1,0,-205,0,-200],['شريط قياس',1,1,120,-155,62,-145],['زاوية نجارة',2,1,230,-70,110,-65]];
function render(){if(state.view==='entry'){app.innerHTML=`<section class="entry"><div><div class="eyebrow">WAREHOUSE / 01</div><h1>كل قطعة،<br>في مكانها.</h1><p>استكشف المستودع، اختر موقع التخزين، وافتح صندوق المعدات.</p><button class="qr-entry" data-action="enter"><img src="entry-qr.svg" alt="رمز QR لفتح خريطة المستودع"><span>اضغط للدخول<br><small>أو امسح الرمز بجوالك</small></span></button><p class="note">واجهة لمس • راجع الكمية والحالة المعتمدة قبل الاستلام</p><div class="stats"><div><b>05</b><span>صفوف</span></div><div><b>08</b><span>واجهات تخزين</span></div><div><b>192</b><span>موقعًا محددًا</span></div></div></div><img class="entry-image" src="warehouse.png" alt="المستودع: صفان مفردان عند الجدارين وثلاثة صفوف مزدوجة في الوسط"></section>`;return}
if(state.view==='map')renderMap();else renderCase();}
function renderMap(){app.innerHTML=`<div class="topline"><div><div class="eyebrow">خريطة المستودع</div><h1>اختر موقع التخزين</h1></div><button data-action="entry">مقدمة المستودع</button></div><div class="workspace"><section class="map-panel"><div class="map-head"><h2>المستودع من الأعلى</h2><span class="legend">اضغط على رقم القسم داخل الصف</span></div><div class="floor">${[1,2,3,4,5].map(r=>`<div class="rowgroup"><button class="rowtitle ${state.row===r?'active':''}" data-row="${r}">${rowNames[r]}</button><div class="faces">${(r===1||r===5?['A']:['A','B']).map(s=>`<div class="face"><span class="face-label">${s}</span>${[6,5,4,3,2,1].map(b=>`<button class="bay ${state.row===r&&state.side===s&&state.bay===b?'selected':''}" data-row="${r}" data-side="${s}" data-bay="${b}" aria-label="${rowNames[r]} الجهة ${s} القسم ${b}" aria-pressed="${state.row===r&&state.side===s&&state.bay===b}">${pad(b)}</button>`).join('')}</div>`).join('')}</div></div>`).join('')}</div><div class="entrance">المدخل • يبدأ القسم 01 من جهة المدخل</div></section><aside class="details"><h2>${rowNames[state.row]} · القسم ${pad(state.bay)}</h2><div><div class="detail-label">الجهة</div><div class="toggle">${(state.row===1||state.row===5?['A']:['A','B']).map(s=>`<button data-side="${s}" class="${state.side===s?'selected':''}" aria-pressed="${state.side===s}">${s}</button>`).join('')}</div></div><div><div class="detail-label">مستوى الرف</div><div class="levels">${[4,3,2,1].map(l=>`<button class="level ${state.level===l?'selected':''}" data-level="${l}" aria-pressed="${state.level===l}"><span>لفل ${l}</span><small>${l===4?'أعلى رف':l===1?'أسفل رف':''}</small></button>`).join('')}</div></div><div class="address">${code()}</div>${state.row===1?`<p class="note">${locationBoxes().length} صناديق في الموقع المحدد · إجمالي برافو ${window.warehouseAllBoxes?window.warehouseAllBoxes().filter(b=>b.row===1).length:32} صندوقًا</p>`:""}<button class="primary wide" data-action="inspect">عرض الموقع ←</button><p class="note">الصندوق التجريبي: الاسبير، الجهة A، القسم 05، لفل 2.</p><button class="primary wide" data-action="rb001">تجربة فتح RB-001</button><button class="wide" data-action="sample">الانتقال للصندوق التجريبي</button></aside></div>`;}
function renderCase(){if(locationBoxes().length){renderBravo();return;}app.innerHTML=`<div class="topline"><div><div class="breadcrumbs">${rowNames[state.row]} / الجهة ${state.side} / القسم ${pad(state.bay)} / لفل ${state.level}</div><h1>${sample()?'صندوق أدوات النجارة':'موقع التخزين'}</h1></div><button data-action="back">رجوع إلى الخريطة ←</button></div>${sample()?`<div class="inspect"><section class="stage" aria-label="عرض صندوق المعدات"><div class="stage-label"><b dir="ltr">${code()}</b><small>صندوق 01 · محتويات تجريبية</small></div>${toolsList.map((t,i)=>`<div class="tool" style="--x:${t[3]}px;--y:${t[4]}px;--mx:${t[5]}px;--my:${t[6]}px;transition-delay:${i*70}ms"><div class="sprite" style="background-position:${t[1]*100/3}% ${t[2]*100}%" role="img" aria-label="${t[0]}"></div><span>${t[0]}</span></div>`).join('')}<button class="case sprite" data-action="toggle" aria-label="فتح صندوق الأدوات" aria-expanded="false"></button><span class="statusline" id="case-status">اضغط على الصندوق لفتحه</span></section><aside class="details"><h2>محتويات الصندوق</h2><ul class="inventory">${toolsList.map(t=>`<li><span>${t[0]}</span><span>1</span></li>`).join('')}</ul><button class="primary wide" id="toggle" data-action="toggle">فتح الصندوق</button><p class="note">عند الرجوع تعود الأدوات إلى الصندوق ثم يُغلق تلقائيًا.</p></aside></div>`:`<section class="map-panel empty"><div class="eyebrow" dir="ltr">${code()}</div><h2>لم تُضف محتويات لهذا الموقع</h2><p class="muted">الموقع متاح في النموذج، ولا توجد بيانات مخزون فعلية مرتبطة به.</p><br><button class="primary" data-action="sample">عرض صندوق أدوات النجارة التجريبي</button></section>`}`;}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function setOpen(open){if(state.busy)return;state.busy=true;document.querySelectorAll('[data-action="toggle"],[data-action="back"]').forEach(b=>b.disabled=true);const box=document.querySelector('.case'),stage=document.querySelector('.stage');if(open){box.classList.add('open');await delay(200);stage.classList.add('opened');await delay(1000);}else{stage.classList.remove('opened');await delay(1000);box.classList.remove('open');await delay(200);}state.open=open;state.busy=false;box.setAttribute('aria-expanded',open);box.setAttribute('aria-label',open?'إغلاق صندوق الأدوات':'فتح صندوق الأدوات');document.getElementById('toggle').textContent=open?'إرجاع الأدوات وإغلاق الصندوق':'فتح الصندوق';document.getElementById('case-status').textContent=open?'5 أدوات · عرض تجريبي':'اضغط على الصندوق لفتحه';document.querySelectorAll('[data-action="toggle"],[data-action="back"]').forEach(b=>b.disabled=false);document.getElementById('announce').textContent=open?'فُتح الصندوق وظهرت خمس أدوات':'عادت الأدوات وأُغلق الصندوق';}
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||state.busy)return;const d=b.dataset;if(Object.keys(d).some(k=>k.startsWith('wh')))return;if(await handleRbAction(d))return;if(d.box){state.box=d.box;renderBravo();return;}if(d.action==='boxes'){state.box=null;renderBravo();return;}if(d.action==='toggle'){await setOpen(!state.open);return;}if(d.action==='back'){if(state.open)await setOpen(false);state.view='map';}else if(d.action==='enter')state.view='map';else if(d.action==='entry')state.view='entry';else if(d.action==='inspect'){state.view='case';state.open=false;state.box=null;}else if(d.action==='sample'){Object.assign(state,{row:3,side:'A',bay:5,level:2,view:'case',open:false});}else{if(d.row){state.row=+d.row;if(state.row===1||state.row===5)state.side='A';}if(d.side)state.side=d.side;if(d.bay)state.bay=+d.bay;if(d.level)state.level=+d.level;}render();});if(location.hash==='#rb001'){Object.assign(state,{row:1,side:'A',bay:5,level:1,view:'case',box:'bravo-s5-l1-box2'});}render();
